<?php use Namira\StoreCatalog; ?>
<link rel="stylesheet" href="/assets/store.css?v=009">
<section class="store-intro"><div><p class="muted">فروشگاه نامیرا</p><h1>یاد و هنر، در زندگی روزمره</h1><p>محصولات آماده و طراحی اختصاصی توسط تیم نامیرا</p></div><a class="outline" href="<?= e(url('shop',['production'=>'custom'])) ?>">محصولات قابل شخصی‌سازی</a></section>
<div class="store-layout"><aside><details class="store-filter" open><summary>جست‌وجو و فیلتر محصولات</summary><form method="get"><input type="hidden" name="page" value="shop"><label>جست‌وجو<input name="q" maxlength="150" value="<?= e($f['q']??'') ?>" placeholder="نام، کد یا ویژگی محصول"></label><label>دسته‌بندی<select name="category"><option value="">همه دسته‌ها</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($f['category']??0)===(int)$c['id']?'selected':'' ?>><?= e(($c['parent_id']?'↳ ':'').$c['title']) ?></option><?php endforeach ?></select></label>
<?php foreach(['delivery'=>['روش تحویل',StoreCatalog::DELIVERY],'production'=>['شیوه آماده‌سازی',StoreCatalog::PRODUCTION]] as $key=>[$label,$options]): ?><label><?= $label ?><select name="<?= $key ?>"><option value="">همه</option><?php foreach($options as $v=>$t): ?><option value="<?= $v ?>" <?= ($f[$key]??'')===$v?'selected':'' ?>><?= e($t) ?></option><?php endforeach ?></select></label><?php endforeach ?>
<div class="store-two"><label>حداقل قیمت (تومان)<input type="number" min="0" max="1000000000" name="min_price" value="<?= e($f['min_price']??'') ?>"></label><label>حداکثر قیمت (تومان)<input type="number" min="0" max="1000000000" name="max_price" value="<?= e($f['max_price']??'') ?>"></label></div>
<label class="store-check"><input type="checkbox" name="in_stock" value="1" <?= !empty($f['in_stock'])?'checked':'' ?>>فقط موجود</label><label class="store-check"><input type="checkbox" name="discounted" value="1" <?= !empty($f['discounted'])?'checked':'' ?>>دارای تخفیف</label>
<?php foreach($attributes as $attribute): ?><details><summary><?= e($attribute['title']) ?></summary><?php foreach($attribute['values'] as $v): ?><label class="store-check"><input type="checkbox" name="attribute[<?= (int)$attribute['id'] ?>][]" value="<?= (int)$v['id'] ?>" <?= in_array((string)$v['id'],array_map('strval',$f['attribute'][$attribute['id']]??[]),true)?'checked':'' ?>><?= e($v['title']) ?></label><?php endforeach ?></details><?php endforeach ?>
<label>مرتب‌سازی<select name="sort"><?php foreach(['new'=>'جدیدترین','relevant'=>'مرتبط‌ترین','best'=>'پرفروش‌ترین','featured'=>'ویژه','price'=>'ارزان‌ترین','price_desc'=>'گران‌ترین'] as $v=>$t): ?><option value="<?= $v ?>" <?= ($f['sort']??'new')===$v?'selected':'' ?>><?= $t ?></option><?php endforeach ?></select></label><button class="primary">نمایش محصولات</button> <a href="<?= e(url('shop')) ?>">پاک کردن فیلترها</a></form></details></aside>
<section><p class="muted" role="status"><?= fa($result['count']) ?> محصول</p><?php if(!$result['items']): ?><div class="empty"><h2>محصولی پیدا نشد</h2><p>فیلترهای دیگری انتخاب کنید یا بعداً دوباره سر بزنید.</p><a href="<?= e(url('shop')) ?>">همه محصولات</a></div><?php else: ?><div class="store-grid"><?php foreach($result['items'] as $p): ?><article class="store-card"><a href="<?= e(url('product',['id'=>$p['id']])) ?>"><?php if($p['cover_id']||$p['image_id']): ?><img loading="lazy" width="400" height="400" src="<?= e($p['cover_id']?url('store-media',['id'=>$p['cover_id']]):url('media',['id'=>$p['image_id']])) ?>" alt="<?= e($p['title']) ?>"><?php else: ?><div class="store-placeholder" aria-hidden="true">ن</div><?php endif ?><div class="store-card-content"><?php if($p['production']==='custom'): ?><span class="store-badge">قابل شخصی‌سازی</span><?php endif ?><p class="muted"><?= e(StoreCatalog::DELIVERY[$p['delivery']]) ?></p><h2><?= e($p['title']) ?></h2><p class="price"><?php if($p['pricing']==='quote'): ?>استعلام قیمت<?php else: ?><?= $p['pricing']==='variable'?'از ':'' ?><?= fa(number_format((int)$p['min_price'])) ?> <small>تومان</small><?php endif ?></p><p class="muted"><?= $p['available']?'مشاهده و انتخاب گزینه‌ها':'مشاهده محصول' ?></p></div></a></article><?php endforeach ?></div><?php endif ?>
<?php if($result['pages']>1): ?><nav class="store-pagination" aria-label="صفحه‌بندی محصولات"><?php for($i=max(1,$result['page']-2);$i<=min($result['pages'],$result['page']+2);$i++): ?><a class="outline" <?= $i===$result['page']?'aria-current="page"':'' ?> href="<?= e(url('shop',array_replace($f,['p'=>$i]))) ?>"><?= fa($i) ?></a><?php endfor ?></nav><?php endif ?></section></div>
